<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElButton, ElDialog, ElIcon, ElMessageBox, ElSelect, ElOption } from 'element-plus'
import { ChatDotRound, Clock, Plus, Setting, List, Delete, DocumentChecked, Search, ArrowRight } from '@element-plus/icons-vue'
import { assistantState, activeRun, selectedRun, pendingOperations, useAssistant, newConversation, selectConversation, deleteConversation, selectRun } from './state'
import ConversationPane from './components/ConversationPane.vue'
import OperationCard from './components/OperationCard.vue'
import ResultContent from './components/ResultContent.vue'
import ToolCatalog from './components/ToolCatalog.vue'
import AssistantTasks from './components/AssistantTasks.vue'
const route = useRoute(), router = useRouter()
const historyOpen = ref(false), toolsOpen = ref(false), tab = ref<'chat' | 'results'>('chat')
let dispose: (() => void) | undefined
onMounted(() => { dispose = useAssistant(typeof route.query.conversation === 'string' ? route.query.conversation : undefined) })
onBeforeUnmount(() => dispose?.())
watch(() => assistantState.detail?.conversation.id, id => { if (id && route.query.conversation !== id) void router.replace({ query: { ...route.query, conversation: id } }) })
watch(() => route.query.conversation, id => { if (typeof id === 'string' && id !== assistantState.detail?.conversation.id) void selectConversation(id) })
watch(() => pendingOperations.value.length, count => { if (count) tab.value = 'results' })
const operations = computed(() => assistantState.detail?.operations.filter(o => o.runId === assistantState.selectedRunId) ?? [])
const results = computed(() => assistantState.events.filter(e => e.kind === 'tool_result'))
const resultCount = computed(() => operations.value.length + results.value.length)
const taskIds = computed(() => {
  const ids = new Set<string>()
  for (const result of [...operations.value.map(o => o.result), ...results.value.map(e => e.data.result)]) {
    if (!result || typeof result !== 'object') continue
    const tasks = (result as { tasks?: { id?: string }[] }).tasks
    if (Array.isArray(tasks)) for (const task of tasks) if (typeof task.id === 'string') ids.add(task.id)
    const collect = (item: unknown) => { if (item && typeof item === 'object' && 'businessId' in item && 'progress' in item && 'id' in item && typeof item.id === 'string') ids.add(item.id) }
    collect(result)
    if ('items' in result && Array.isArray(result.items)) result.items.forEach(collect)
  }
  return [...ids]
})
const states: Record<string, string> = { RUNNING: '正在执行', WAITING: '等待确认', COMPLETED: '已完成', FAILED: '执行失败', STOPPED: '已停止', INTERRUPTED: '服务重启后已中断' }
const groups = [{ title: '歌曲', page: '/library/songs' }, { title: '下载歌曲', page: '/library/downloads' }, { title: '原唱与伴奏', page: '/library/audio-processing' }, { title: '模型服务', page: '/system/ai/models' }, { title: '后台任务', page: '/system/tasks' }]
async function openConversation(id: string) { historyOpen.value = false; await selectConversation(id) }
async function remove(id: string) { try { await ElMessageBox.confirm('将删除这个会话的消息、运行记录和确认记录。已创建的歌单和业务任务会保留。', '删除会话', { confirmButtonText: '删除会话', cancelButtonText: '保留', type: 'warning' }); await deleteConversation(id) } catch { /* User kept the history. */ } }
function time(value: string) { return new Date(value).toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }) }
function safePage(value: unknown) { return typeof value === 'string' && value !== '/system/assistant' && /^\/(library|system)(\/|$)/.test(value) ? value : '' }
</script>
<template>
  <section class="assistant-workbench">
    <header class="workbench-heading"><div><div class="workbench-title"><h1>管理助手</h1><span class="workbench-availability"><span :class="{ ready: assistantState.status?.ready }" />{{ assistantState.status?.ready ? '已就绪' : '等待配置' }}</span></div></div><div class="workbench-actions"><ElButton :icon="Clock" @click="historyOpen = true">会话历史</ElButton><ElButton :icon="Plus" :disabled="assistantState.busy" @click="newConversation">新建对话</ElButton><RouterLink to="/system/ai/features/assistant" class="workbench-settings" aria-label="助手设置"><ElIcon><Setting /></ElIcon></RouterLink></div></header>
    <nav class="workbench-mobile-tabs" aria-label="助手视图"><button :aria-current="tab === 'chat' ? 'page' : undefined" @click="tab = 'chat'"><ElIcon><ChatDotRound /></ElIcon>对话</button><button :aria-current="tab === 'results' ? 'page' : undefined" @click="tab = 'results'"><ElIcon><DocumentChecked /></ElIcon>结果与操作<span v-if="pendingOperations.length">{{ pendingOperations.length }} 待确认</span></button></nav>
    <div class="workbench-body sv-glass" :class="`mobile-${tab}`">
      <section class="workbench-results" aria-label="结果与操作">
        <header class="results-heading"><div><ElIcon><DocumentChecked /></ElIcon><strong>结果与操作</strong><span v-if="resultCount" class="results-count">{{ resultCount }}</span></div><ElButton text :icon="List" @click="toolsOpen = true">工具目录</ElButton></header>
        <div v-if="assistantState.detail?.runs.length" class="run-picker"><ElSelect :model-value="assistantState.selectedRunId" aria-label="查看哪次运行的结果" @change="id => selectRun(String(id))"><ElOption v-for="(run, index) in assistantState.detail.runs" :key="run.id" :value="run.id" :label="`${index + 1}. ${assistantState.detail.messages.find(m => m.runId === run.id && m.role === 'user')?.content.slice(0, 30) ?? '对话'} — ${states[run.status] ?? run.status}`" /></ElSelect><span :class="{ 'run-pending': selectedRun?.status === 'WAITING' }">{{ selectedRun ? states[selectedRun.status] : '' }}</span></div>
        <div class="results-scroll">
          <AssistantTasks :ids="taskIds" />
          <template v-if="resultCount"><OperationCard v-for="operation in operations" :key="operation.id" :operation="operation" /><article v-for="event in results" :key="event.sequence" class="query-result"><header><ElIcon><Search /></ElIcon><h3>{{ event.data.title || '查询结果' }}</h3><span>{{ time(event.createdAt) }}</span></header><p v-if="event.data.error" class="query-error" role="status">{{ event.data.error }}</p><ResultContent v-else :value="event.data.result" /><RouterLink v-if="safePage(event.data.page)" :to="safePage(event.data.page)" class="result-page">在业务页面查看 <ElIcon><ArrowRight /></ElIcon></RouterLink></article></template>
          <div v-else class="results-welcome"><h2>{{ activeRun ? '正在处理…' : '快捷入口' }}</h2><div class="capability-list"><RouterLink v-for="group in groups" :key="group.title" :to="group.page"><strong>{{ group.title }}</strong><ElIcon><ArrowRight /></ElIcon></RouterLink></div></div>
        </div>
        <footer class="results-footer"><span>{{ assistantState.status?.toolCount ?? 0 }} 个内置工具</span><RouterLink to="/system/tasks">后台任务中心</RouterLink></footer>
      </section>
      <ConversationPane class="workbench-conversation" @results="tab = 'results'" />
    </div>
    <ElDialog v-model="historyOpen" title="会话历史" width="min(620px, calc(100vw - 32px))" class="assistant-history-dialog" :close-on-click-modal="false"><div class="history-list"><div v-for="conversation in assistantState.conversations" :key="conversation.id" class="history-row" :class="{ selected: assistantState.detail?.conversation.id === conversation.id }"><button @click="openConversation(conversation.id)"><strong>{{ conversation.title }}</strong><span>{{ time(conversation.updatedAt) }}<small v-if="conversation.activeRunId">有活动运行</small></span></button><ElButton text :icon="Delete" :disabled="!!conversation.activeRunId || assistantState.busy" :aria-label="`删除会话 ${conversation.title}`" @click="remove(conversation.id)" /></div><p v-if="!assistantState.conversations.length" class="history-note">还没有对话记录。</p></div></ElDialog>
    <ElDialog v-model="toolsOpen" title="内置工具目录" width="min(800px, calc(100vw - 32px))"><ToolCatalog :tools="assistantState.tools" /></ElDialog>
  </section>
</template>
<style scoped>
