elected{background:var(--sv-surface-2)}.history-row>button:first-child{flex:1;display:flex;flex-direction:column;gap:10px;text-align:left;min-width:0;padding:16px 12px;border:0;background:transparent;color:var(--sv-text-primary);font:inherit;cursor:pointer}.history-row strong{font-size:14px;font-weight:550;overflow-wrap:anywhere}.history-row span{font-size:12px;color:var(--sv-text-secondary)}.history-row small{font-size:12px;margin-left:14px;color:var(--sv-accent-primary)}.history-row .el-button{min-width:44px;min-height:44px}.workbench-mobile-tabs{display:none}@media(max-width:1000px){.workbench-body{grid-template-columns:minmax(0,1fr) minmax(340px,1fr)}.results-scroll{padding:18px}.capability-list{grid-template-columns:1fr}.capability-list a:nth-child(even){padding-left:0;border-left:0}.capability-list a{padding:16px 0}.results-heading{padding:8px 18px}.workbench-heading{gap:12px}.workbench-actions .el-button{padding:12px}}@media(max-width:760px){.workbench-heading{align-items:flex-start;flex-direction:column;margin-bottom:18px;gap:16px}.workbench-title h1{font-size:24px}.workbench-actions{width:100%}.workbench-actions .el-button{flex:1}.workbench-body{display:block;height:max(620px,calc(100dvh - 290px));border-radius:0 0 12px 12px;max-height:none}.workbench-mobile-tabs{display:flex;border:1px solid var(--sv-border-default);border-bottom:0;border-radius:12px 12px 0 0;background:var(--sv-surface-1)}.workbench-mobile-tabs button{display:flex;gap:8px;align-items:center;justify-content:center;min-height:48px;flex:1;font:inherit;font-size:14px;background:transparent;border:0;border-bottom:2px solid transparent;color:var(--sv-text-secondary);cursor:pointer}.workbench-mobile-tabs button[aria-current]{color:var(--sv-accent-primary);border-bottom-color:var(--sv-accent-primary);font-weight:600}.workbench-mobile-tabs span{font-size:12px}.workbench-results,.workbench-conversation{height:100%;border-right:0}.mobile-chat .workbench-results,.mobile-results .workbench-conversation{display:none}.results-welcome{margin:4px auto}.capability-list{grid-template-columns:1fr 1fr}.capability-list a:nth-child(even){padding-left:16px;border-left:1px solid var(--sv-border-default)}.query-result{padding:18px}.query-result header>span{display:none}.results-scroll{padding:18px}.run-picker{padding:12px 18px}.run-picker>span{display:none}.results-footer{padding:12px 18px}}
</style>
